function not(a) {
  return a === 'T' ? 'F' : a === 'F' ? 'T' : a;
}

function and(a, b) {
  const order = [Val.N, Val.F, Val.B, Val.T];
  return order[Math.max(order.indexOf(a), order.indexOf(b))];
}

function or(a, b) {
  const order = [Val.N, Val.F, Val.B, Val.T];
  return order[Math.min(order.indexOf(a), order.indexOf(b))];
}

function evaluate(expr, vars) {
  // Recursive evaluation of constraint expressions
